interface.definition:
a!localVariables(


/* Get ASSIGNED team roles */
local!applicationdetails: if(
  a!isNotNullOrEmpty(ri!teamid),
  #"_a-0000eef8-4604-8000-9e54-011c48011c48_1138645"(teamid: ri!teamid, isActive: true()),
  null()
),

/* Extract assigned groupids from team roles */
local!assignedGroupids: if(
  a!isNotNullOrEmpty(local!applicationdetails),
  index(
    local!applicationdetails,
    #"urn:appian:record-field:v1:139cb21e-dd78-4694-a8ad-b43e2d51226f/da39fffc-c223-49f0-b99c-5a3a8f8ad3b8",
    {}
  ),
  {}
),

local!teamorganizationdetails: if(
  a!isNotNullOrEmpty(ri!teamid),
  #"_a-0000eef8-4604-8000-9e54-011c48011c48_1134349"(teamid: ri!teamid, isActive: true()),
  null()
),

local!organizationid: index(
  local!teamorganizationdetails,
  #"urn:appian:record-field:v1:4eb1fdb2-adfe-4b4b-8a61-ccc9f1f5f947/96d37d06-45e7-4282-8de1-85e282e0ef8b",
  null()
),

local!organizationapplication: if(
  a!isNotNullOrEmpty(local!organizationid),
  #"_a-0000eef8-4604-8000-9e54-011c48011c48_1142076"(orgId: local!organizationid, isActive: true()),
  null()
),

local!orgapproles: if(
  a!isNotNullOrEmpty(local!organizationapplication),
  index(
    local!organizationapplication,
    #"urn:appian:record-field:v1:0723a91a-4d09-404f-821d-4296dd50e6c6/26a43997-9c33-40cd-a0e1-cf6a4c80387b",
    null()
  ),
  null()
),

local!approles: if(
  a!isNotNullOrEmpty(local!orgapproles),
  #"_a-0000eef8-4604-8000-9e54-011c48011c48_1136641"(applicationid: local!orgapproles),
  null()
),

local!appids: if(
  a!isNotNullOrEmpty(local!approles),
  index(
    local!approles,
    #"urn:appian:record-field:v1:a54a3394-393d-4e6a-8737-0e73bb9b47e6/42950c36-a377-4597-bd74-3eeceefd7079",
    null()
  ),
  null()
),

{
